) AS v(pin, office)
JOIN nss.postal_code pc ON pc.postal_code = v.pin
ON CONFLICT (postal_code_pk, post_office_name)
    WHERE entry_status = 'APPROVED' AND is_active = TRUE
    DO NOTHING;

